mapper.sql:
WHERE g.is_delete = 0

    AND g.status = #{query.status}


    AND (g.goods_name LIKE CONCAT('%', #{query.keyword}, '%') OR g.spu_code LIKE CONCAT('%', #{query.keyword}, '%'))


    AND g.category_id = #{query.categoryId}


    AND g.stock_num > COALESCE(g.warn_stock, #{query.warnStock})


    AND g.stock_num > 0 AND g.stock_num <= COALESCE(g.warn_stock, #{query.warnStock})


    AND g.stock_num <= 0


    AND DATE(g.create_time) >= #{query.startDate}


    AND DATE(g.create_time) <= #{query.endDate}
